import logging
import time

from taf.fdsw.rc.clients.exceptions import TimeoutExceeded
from taf.fdsw.rc.interfaces.exceptions import OperationFailure
from taf.fdsw.rc.interfaces.FDSW18SP.swm import Package, SoftwareManagement
from taf.fdsw.rc.schemas.FDSW18SP.swm import (RunningSofware,
                                              SoftwareUpdateStatus)

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())
logging.basicConfig(level=logging.INFO)


class SoftwareManagement20B(SoftwareManagement):

    def __init__(self, client):
        super(SoftwareManagement20B, self).__init__(client)

    def get_running_sw_version_name(self, timeout=10):
        sw_info = self.get_all_software_inventory(timeout=timeout)
        for slot in sw_info.slots:
            if slot.running is True:
                return slot.version

    def get_all_software_inventory(self, timeout=10):
        all_sw_inventory = self._client.send(
            method='software.fetch',
            parameters={},
            timeout=timeout
        )
        sw_inventory = RunningSofware.from_object_dict(all_sw_inventory.data)
        return sw_inventory

    def get_active_sw_partition(self, timeout=10):
        all_sw_inventory = self.get_all_software_inventory()
        for slot in all_sw_inventory.slots:
            if slot.mode == 'Active':
                return slot.id

    def software_rollback(self, sw_slot_id, timeout=10, **kwargs):
        try:
            self._client.send(
                method='software.rollback',
                timeout=timeout,
                parameters={"slotId": str(sw_slot_id)})
        except TimeoutExceeded:
            logging.info('Connection closed due to rollback operation')
        finally:
            self._client.disconnect()

    def software_update(self, sw_pkg_path, activate=False, timeout=360, **kwargs):
        package = Package(sw_pkg_path)

        targetBD = self._get_targetBD_file(package)
        initialized_update_status = self.initialize_sw_update(targetBD, activate, timeout, **kwargs)
        self._upload_files_to_sw_update(package, initialized_update_status, timeout)
        self.last_targetBD = targetBD
        self.last_package = package

        logger.info('Software update succeeded.')
        if activate:
            self._client.disconnect()
            logger.info('Node B reset ... closing connection')

    def upload_a_file(self, next_file_name, package, timeout):
        payload = package.read_file(next_file_name)
        resp = self._client.send(
            method='software.uploadFile',
            parameters={'filename': next_file_name},
            payload=payload,
            timeout=timeout
        )
        return resp

    def initialize_sw_update(self, targetBD, activate, timeout, **kwargs):
        logger.info('Starting software update')

        resp = self._client.send(
            method='software.startUpdating',
            parameters={'activate': activate},
            payload=targetBD,
            timeout=timeout
        )
        self._check_sw_update_response(resp)
        targetBD_update_status = SoftwareUpdateStatus.from_object_dict(resp.data)
        logger.info('TargetBD file sent. Starting sending other files')
        return targetBD_update_status

    def _upload_files_to_sw_update(self, package, update_status, timeout):
        logger.info('Update progress:')
        update_progress_bar = 0.1

        operation_timeout = timeout + time.time()

        while update_status.next_filename is not None:

            next_file_name = update_status.next_filename
            try:
                resp = self.upload_a_file(next_file_name=next_file_name, package=package, timeout=120)
                self._check_sw_update_response(resp)
                update_status = SoftwareUpdateStatus.from_object_dict(resp.data)

                if self._check_if_sw_already_installed(update_status):
                    break

                if update_status.update_progress > update_progress_bar:
                    logger.info(round(update_status.update_progress, 1))
                    update_progress_bar += 0.1

                if time.time() > operation_timeout:
                    raise TimeoutExceeded

            except TimeoutExceeded:
                self._client.disconnect()
                raise OperationFailure('Software update failed')

    @staticmethod
    def _check_sw_update_response(resp):
        if resp.status is False:
            error_msg = 'Software update failed: {}'.format(resp.error)
            raise OperationFailure(error_msg)

    def _get_targetBD_file(self, package):
        files = package.find_filepaths('TargetBD')
        if len(files) == 1:
            return package.read_file(files[0])
        raise OperationFailure('Files with name TargetBD found: {}'.format(len(files)))

    @staticmethod
    def _check_if_sw_already_installed(update_status):
        if update_status.next_filename is None and update_status.update_progress == 0.0:
            error_msg = 'Requested SW Release is already installed on desired slot'
            logger.info(error_msg)
            return True
        return False
